SELECT MIN(L.ID) ID, MIN(COALESCE(LC.TITULO, L.TITULO)) TITULO, COALESCE(MAX(LC.AUTOR), MAX(NULLIF(L.AUTOR, ''))) AUTOR, MAX(LC.STATUS_LEITURA) STATUS, COUNT(*) INDICACOES, COUNT(DISTINCT L.VIDEO_ID) VIDEOS, GROUP_CONCAT(DISTINCT C.NOME ORDER BY C.NOME SEPARATOR ', ') CANAIS FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci LEFT JOIN LIVROS_CATALOGO LC ON LC.ID = N.CATALOGO_ID JOIN VIDEOS V ON V.ID = L.VIDEO_ID JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE V.STATUS = 'ESTUDADO' AND (N.ID IS NULL OR N.ESTADO = 'OK') AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}}) AND ('{{busca}}' = '' OR CONCAT(COALESCE(LC.TITULO, L.TITULO), ' ', COALESCE(LC.AUTOR, L.AUTOR, '')) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{status}}' = '' OR ('{{status}}' = 'NENHUM' AND LC.STATUS_LEITURA IS NULL) OR LC.STATUS_LEITURA = '{{status}}') AND ('{{titulo}}' = '' OR COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{titulo}}', '%')) AND ('{{autor}}' = '' OR COALESCE(LC.AUTOR, L.AUTOR, '') COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{autor}}', '%')) AND ('{{fav}}' = '' OR EXISTS (SELECT 1 FROM ITENS_FAVORITOS FV WHERE FV.TIPO = 'LIVRO' AND FV.NOME COLLATE utf8mb4_0900_ai_ci = COALESCE(LC.TITULO, L.TITULO))) GROUP BY COALESCE(LC.TITULO, L.TITULO) COLLATE utf8mb4_0900_ai_ci ORDER BY IF('{{ordem}}' = 'az', 0, COUNT(DISTINCT L.VIDEO_ID)) DESC, TITULO LIMIT {{limit}} OFFSET {{offset}}